Translate("ruRU", "redridge-mountains", {
	title = "Красногорье",
	aliases = { "Красногорье" },
	sections = {
		{
			title = "Обзор",
			text = [=[Красногорье поднимается к востоку от {link:elwynn-forest}Элвиннского леса{/link} — край красных каменных кряжей, высоких вязов и быстрых холодных рек. В его сердце лежит {link:lake-everstill}Озеро Безмолвия{/link}, а на западном берегу озера стоит {link:lakeshire}Приозерье{/link}, самый восточный городок {link:kingdom-of-stormwind}королевства Штормград{/link}. Дороги отсюда ведут на запад в Элвиннский лес, на юго-запад в {link:duskwood}Сумеречный лес{/link} и на север, через перевал, в {link:burning-steppes}Пылающие степи{/link}. В лучшие годы Красногорье было землей рыбаков, мельников и рудокопов. В нынешние дни это земля войны, и ведет она эту войну почти в одиночку.]=],
		},
		{
			title = "Истоки",
			text = [=[Ни одна летопись не называет года, когда первые люди поселились в Красногорье. Пока {link:stormwind-city}Штормград{/link} богател на пашнях своих срединных земель, его народ расселялся по окрестным холмам, и со временем на берегу озера вырос город. Говорят, что некогда горы тянулись дальше на север. Когда {link:dark-iron-dwarves}дворфы Черного Железа{/link} воззвали к Повелителю Огня в войне против своих сородичей, пламя, воздвигшее {link:blackrock-mountain}Черную гору{/link}, выжгло северные хребты и обратило их в засыпанную пеплом пустошь, которую ныне зовут Пылающими степями. Южные долины остались зелеными и остались в руках людей.]=],
		},
		{
			title = "Наши дни",
			text = [=[{link:orcs}Орки{/link} {link:blackrock-clan}клана Черной горы{/link} спустились из Пылающих степей. В союзе с чернокнижником {link:morganth}Моргантом{/link} они взяли штурмом {link:stonewatch-keep}Крепость Каменной Стражи{/link} и перебили большую часть державших ее солдат. Затем чернокнижник обратился против своих союзников и возвел на северо-востоке собственную башню, где ему служат {link:shadowhide-gnolls}гноллы-Темношкуры{/link}. Орки двинулись дальше, на само {link:lakeshire}Приозерье{/link}, и натиск их был так яростен, что большой мост через {link:lake-everstill}Озеро Безмолвия{/link} рухнул в воду. {link:magistrate-solomon}Магистрат Соломон{/link} писал о помощи в {link:stormwind-city}Штормград{/link}, в {link:westfall}Западный Край{/link} и в {link:darkshire}Темнолесье{/link}. Помощь не пришла. Городок держится силами горстки стражников, отстроенного моста и чужаков, которые откликаются на его объявления о наградах.

Есть и новое. Купцы одной торговой компании поставили свой пост на перекрестке {link:three-corners}Три Угла{/link}, и новая дорога ведет теперь из Красногорья в сторону земли, что зовется {link:riverglades}Речными полянами{/link}. На дальнем юго-востоке второй боевой отряд клана Черной горы разбил лагерь в Долине Ренда.]=],
		},
		{
			title = "Обитатели",
			text = [=[• {b}Жители Приозерья.{/b} Рыбаки, кузнецы, конюхи и трактирщики, научившиеся жить за баррикадами.
• {b}Стража {link:stormwind-city}Штормград{/link}а.{/b} Небольшой гарнизон под началом маршала {link:marshal-marris}Маррис{/link}а, слишком малый для войны, которую ему приходится вести.
• {b}{link:orcs}Орки{/link} клана Черной горы.{/b} Они держат {link:stonewatch-keep}Крепость Каменной Стражи{/link}, северный перевал и юго-восточные долины.
• {b}{link:shadowhide-gnolls}Гноллы-Темношкуры{/link}.{/b} Они рыщут по Долине {link:galardell-valley}Галарделл{/link} на службе у чернокнижника.
• {b}{link:redridge-gnolls}Гноллы Красногорья{/link}.{/b} Отдельная стая, которая совершает набеги на холмы к северу от Приозерья и на южную дорогу.
• {b}{link:murlocs}Мурлоки{/link}.{/b} Они поднялись по рекам, чтобы выловить всю рыбу в Озере Безмолвия, вдали от всякого моря.
• {b}Детеныши черных драконов.{/b} Они охотятся в холмах к югу от озера, и никто не может сказать, откуда они берутся.]=],
		},
		{
			title = "История",
			text = [=[• {b}{link:first-war}Первая война{/link}.{/b} Когда {link:horde}Орда{/link} прошла через {link:dark-portal}Темный портал{/link}, она сжигала деревни по всему Красногорью, как и в {link:elwynn-forest}Элвинн{/link}ском лесу и в Западном Крае.
• {b}{link:second-war}Вторая война{/link} и после.{/b} Орда была разбита, и то, что осталось от клана Черной горы, отступило в Черную гору.
• {b}Наши дни.{/b} Теперь {link:blackrock-clan}клан Черной горы{/link} вновь пришел на юг, и Красногорье стало восточным рубежом королевства.]=],
		},
		{
			title = "Предания гор",
			text = [=[• {link:lake-everstill}Озеро Безмолвия{/link} славится своей пятнистой солнечной рыбой. Рыбаки рассказывают и о чем-то куда более крупном, что движется в глубокой воде.
• Руда {link:rethban-caverns}Ретбан{/link}а слишком мягка, чтобы соперничать с железом, но ее темный, ровный цвет дает чернила, которые ценят писцы.
• {link:marshal-marris}Маршал Маррис{/link} дал имя дикому кабану, что топчет сады Приозерья: {link:glutton}Обжора{/link}.]=],
		},
	},
})

Translate("ruRU", "lakeshire", {
	title = "Приозерье",
	sections = {
		{
			title = "Обзор",
			text = [=[Приозерье стоит на западном берегу Озера Безмолвия — городок каменных домов, с оживленной таверной, ратушей и конюшней. Правят им магистрат {link:magistrate-solomon}Соломон{/link} и его суд, а охраняют маршал {link:marshal-marris}Маррис{/link} и небольшой гарнизон солдат {link:stormwind-city}Штормград{/link}а. Северный его край теперь закрыт баррикадами. Работники, которыми распоряжается бригадир {link:foreman-oslow}Ослоу{/link}, трудятся над восстановлением моста через {link:lake-everstill}Озеро Безмолвия{/link}, обрушенного {link:orcs}орк{/link}ами клана Черной горы при последнем штурме. Таверна — сердце городка. Там повариха Бреанна стряпает из того, что удается раздобыть, трактирщик ждет груза выпивки, который все не приходит, а все разговоры — об орках, {link:gnolls}гнолл{/link}ах и помощи, обещанной Штормградом.]=],
		},
	},
})

Translate("ruRU", "lake-everstill", {
	title = "Озеро Безмолвия",
	aliases = { "Озеро Безмолвия" },
	sections = {
		{
			title = "Обзор",
			text = [=[Озеро Безмолвия заполняет сердце Красногорья, чистое и синее под красными кряжами. Его пятнистая солнечная рыба издавна была гордостью рыбаков Приозерья. Теперь к его берегам во множестве пришли {link:murlocs}мурлок{/link}и: они бросают свои грубые якоря и забирают рыбу себе. Начальнику причала странно видеть их так далеко от моря, и он гадает, от чего они могут бежать. Под водой лежит не только рыба. Когда {link:blackrock-clan}орки клана Черной горы{/link} ударили по лодке, шедшей от разрушенного моста, ее груз пошел ко дну, и озеро оставило его себе.]=],
		},
	},
})

Translate("ruRU", "stonewatch-keep", {
	title = "Крепость Каменной Стражи",
	aliases = { "Каменная Стража" },
	sections = {
		{
			title = "Обзор",
			text = [=[Крепость Каменной Стражи была твердыней, что охраняла для короны восточные пределы Красногорья. Небольшой гарнизон солдат {link:stormwind-city}Штормград{/link}а держал ее, пока не пришли {link:blackrock-clan}орки клана Черной горы{/link}, усиленные темной магией чернокнижника {link:morganth}Моргант{/link}а. {link:orcs}Орки{/link} бились с такой свирепостью, о какой выжившие говорят до сих пор, и крепость пала. Теперь ее стены укрывают военачальника {link:gath-ilzogg}Гат'Илзогг{/link}а и его капитанов, и оттуда орки совершают набеги на север и на запад, в сторону Приозерья. {link:magistrate-solomon}Магистрат Соломон{/link} считает, что крепость — первое, что королевство должно отвоевать.]=],
		},
	},
})

Translate("ruRU", "stonewatch-tower", {
	title = "Башня Каменной Стражи",
	sections = {
		{
			title = "Обзор",
			text = [=[Башня Каменной Стражи — сторожевая башня, что стоит рядом с Крепостью Каменной Стражи. В отличие от крепости, она пережила битву невредимой, и теперь {link:orcs}орк{/link}и сами пользуются ею как дозорной вышкой над дорогой из Приозерья. На самом ее верху, среди бочек, лежит забытый кувшин, в котором когда-то держали скверное пойло. Верховный маг {link:theocritus}Теокрит{/link} выбрал этот кувшин как тайник для одного из своих глифов, чтобы его всевидящее око могло заглянуть в умы тех, кто находится в крепости.]=],
		},
	},
})

Translate("ruRU", "stonewatch-falls", {
	title = "Водопад Каменной Стражи",
	sections = {
		{
			title = "Обзор",
			text = [=[Ниже Каменной Стражи река, вытекающая из Озера Безмолвия, падает со склона и собирается в глубокой заводи в восточных холмах. Это Водопад Каменной Стражи. {link:murlocs}Мурлоки{/link} поставили по его берегам свои хижины и ловят рыбу в его водах, как их сородичи на берегах большого озера. Над водопадом стоят стены потерянной крепости. Водопад лежит между {link:orcs}орк{/link}ами Каменной Стражи и {link:gnolls}гнолл{/link}ами Долины {link:galardell-valley}Галарделл{/link}, и немногие из Приозерья заходят теперь так далеко на восток.]=],
		},
	},
})

Translate("ruRU", "tower-of-ilgalar", {
	title = "Башня Илгалара",
	aliases = { "Илгалар" },
	sections = {
		{
			title = "Обзор",
			text = [=[Башня Илгалара поднимается в северо-восточных холмах Красногорья. Это логово чернокнижника {link:morganth}Морганта{/link}: он возвел ее после того, как обратился против своих союзников-{link:orcs}орк{/link}ов. {link:shadowhide-gnolls}Гноллы-Темношкуры{/link} стерегут подступы к ней, а залы башни увешаны костями драконов, о назначении которых никто снаружи не может догадаться. У ее стен старая статуя льва десятилетиями несет одинокую стражу. Далеко на западе маг {link:theocritus}Теокрит{/link} следит за башней через Око Азоры в {link:tower-of-azora}собственной башне{/link}.]=],
		},
	},
})

Translate("ruRU", "galardell-valley", {
	title = "Долина Галарделл",
	aliases = { "Галарделл" },
	sections = {
		{
			title = "Обзор",
			text = [=[Долина Галарделл лежит на северо-востоке Красногорья, у подножия Башни {link:tower-of-ilgalar}Илгалар{/link}а. Это край {link:gnolls}гнолл{/link}ов-Темношкуров, которые служат чернокнижнику {link:morganth}Моргант{/link}у. Их стоянки заполняют долину, а их вожак, лейтенант {link:lieutenant-fangore}Фэнгор{/link}, держит свой пост в северной ее части. Среди них ходят ткачи тьмы, творящие темную магию чернокнижника. Путники, которые забредают сюда, редко встречают одного-единственного гнолла. {link:shadowhide-gnolls}Темношкуры{/link} откликаются на зов о помощи быстрее любой другой стаи в горах, а на клич своего лейтенанта сбегается вся долина.]=],
		},
	},
})

Translate("ruRU", "alther-s-mill", {
	title = "Лесопилка Альтера",
	sections = {
		{
			title = "Обзор",
			text = [=[Лесопилка Альтера — лесопилка Приозерья в холмах к северо-востоку от городка. {link:foreman-oslow}Бригадир Ослоу{/link} зависит от нее: она дает лес, нужный ему для восстановления моста через {link:lake-everstill}Озеро Безмолвия{/link}. Работать там стало небезопасно. Огромные тарантулы устроили гнезда среди сложенных бревен, и видели, как вокруг лесопилки рыщут {link:blackrock-clan}орки клана Черной горы{/link}. Ослоу винит в этом беспорядке старого Альтера. У лесопилки есть и иное назначение. Агент {link:si-7}SI:7{/link} Луций держит там запертый сундук, и те, кого он обучает воровскому искусству, должны пойти и открыть его.]=],
		},
	},
})

Translate("ruRU", "rethban-caverns", {
	title = "Пещеры Ретбана",
	aliases = { "Ретбан" },
	sections = {
		{
			title = "Обзор",
			text = [=[Пещеры Ретбана уходят глубоко в предгорья к северу от Приозерья. Они получили имя от человека по имени Барт Ретбан, который первым нашел темную руду в их стенах. {link:lakeshire}Приозерье{/link} прежде держало запас этой руды, ибо писцы ценят ее цвет для своих чернил. Теперь в пещерах живут {link:redridge-gnolls}гноллы Красногорья{/link}, и их чернорабочие добывают руду для себя. Работники бригадира слишком заняты обороной города, чтобы идти за ней. Дворф из семьи Ячменеваров, живущий в Приозерье, сделал пещеры испытанием мужества для воинов.]=],
		},
	},
})

Translate("ruRU", "redridge-canyons", {
	title = "Каньоны Красногорья",
	sections = {
		{
			title = "Обзор",
			text = [=[Каньоны Красногорья прорезают холмы к северу от Приозерья, на дороге к Пылающим степям. Это охотничьи угодья {link:gnolls}гнолл{/link}ов Красногорья. Громилы и мистики бродят по кряжам над городской конюшней и крадут всякую лошадь, что отобьется. Их вожак {link:yowler}Ревун{/link} устроил логово в каньонах, и тихими ночами весь город слышит, как его стая воет в холмах. Дальше на север, у перевала, разбил лагерь {link:blackrock-clan}клан Черной горы{/link}, так что {link:lakeshire}Приозерье{/link} зажато между гноллами и {link:orcs}орк{/link}ами.]=],
		},
	},
})

Translate("ruRU", "lakeridge-highway", {
	title = "Озерный тракт",
	sections = {
		{
			title = "Обзор",
			text = [=[Озерный тракт идет на восток от южного моста Приозерья, вдоль южного берега Озера Безмолвия, к Каменной Страже. Его проложили для торговли, и он связывает город с восточными пределами гор. С тех пор как {link:orcs}орк{/link}и взяли крепость, мало какая повозка ездит по нему. {link:gnolls}Гноллы{/link} стоят лагерем вдоль южной дороги, {link:murlocs}мурлок{/link}и охотятся на берегу, а кондоры кружат над холмами. {link:deputy-feldon}Уполномоченный Фелдон{/link} несет дозор на западном его конце и платит за любые вести о том, что собирается вдоль тракта.]=],
		},
	},
})

Translate("ruRU", "three-corners", {
	title = "Три Угла",
	sections = {
		{
			title = "Обзор",
			text = [=[Три Угла — перекресток на западном краю Красногорья. Одна дорога ведет от него в {link:lakeshire}Приозерье{/link}, другая — в {link:goldshire}Златоземье{/link} в {link:elwynn-forest}Элвинн{/link}ском лесу, третья — в {link:darkshire}Темнолесье{/link} в Сумеречном лесу. {link:guard-parker}Стражник Паркер{/link} обходит дозором отрезок дороги в сторону Сумеречного леса. В нынешние дни перекресток стал местом торговли. {link:azeroth}Азерот{/link}ское торговое управление, компания купцов, устроило здесь свой местный узел — с интендантами, конторщиками, мулами и грудой ящиков, ожидающих досмотра. Его посыльные свозят сюда пустые ящики со всего края.]=],
		},
	},
})

Translate("ruRU", "render-s-camp", {
	title = "Лагерь Ренда",
	aliases = { "Скала Ренда" },
	sections = {
		{
			title = "Обзор",
			text = [=[Лагерь Ренда — стоянка клана Черной горы на северо-западе Красногорья, чуть западнее перевала в {link:burning-steppes}Пылающие степи{/link}. Здесь квартируют воители, что возглавляют каждый отряд орочьего войска. За лагерем лежит Скала Ренда, большая пещера, где {link:orcs}орк{/link}и держат своих пленников. Среди них был капрал {link:stormwind-city}Штормград{/link}а, которого уволокли с поля битвы у Крепости Каменной Стражи и чье имя до сих пор висит на объявлении у таверны Приозерья. Следопыты клана Черной горы бродят по холмам вокруг и следят за дорогой с юга.]=],
		},
	},
})

Translate("ruRU", "render-s-valley", {
	title = "Долина Ренда",
	sections = {
		{
			title = "Обзор",
			text = [=[Долина Ренда лежит на дальнем юго-востоке Красногорья, среди холмов над южными лесами. {link:blackrock-clan}Клан Черной горы{/link} поставил лагеря и здесь, вне досягаемости Каменной Стражи, и его призыватели и скороходы собираются в долине, далеко за пределами досягаемости немногих дозоров Приозерья. {link:marshal-marris}Маршал Маррис{/link} знал об {link:orcs}орк{/link}ах в этом углу гор, но не знал, сколько их. Теперь там обосновался боевой отряд под началом испепелителя {link:incinerator-gar-im}Гар'им{/link}а, чьи заклинатели тьмы, говорят, опаснейшие в своем роде.]=],
		},
	},
})

Translate("ruRU", "magistrate-solomon", {
	title = "Магистрат Соломон",
	subtitle = "Магистрат Приозерья",
	found = "Ратуша Приозерья",
	hint = [=[Поговорите с судьей, который управляет Приозерьем из его ратуши.]=],
	allegiance = "Королевство Штормград · Городок Приозерье",
	aliases = { "Соломон" },
	sections = {
		{
			title = "Обзор",
			text = [=[Магистрат Соломон управляет городком {link:lakeshire}Приозерье{/link} и вершит суд в его судебной палате. Это человек закона и письма, и то и другое он обратил в оружие. Его указы называют врагов королевства, а его награды платят за их головы. Но больше всего он доверяет своим письмам. Вновь и вновь он писал великим и могущественным, умоляя их спасти его город.]=],
		},
		{
			title = "Значение",
			text = [=[Соломон говорит от имени забытого рубежа. Его мольбы одна за другой открывают, что {link:lakeshire}Приозерье{/link} не одиноко в своей покинутости. {link:westfall}Западный Край{/link} и {link:darkshire}Темнолесье{/link} тоже брошены на произвол судьбы, и Соломон начинает подозревать, что в {link:stormwind-city}Штормград{/link}е что-то глубоко неладно.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он объявил смерть ценой за помощь врагу королевства и применяет этот закон против {link:gnolls}гнолл{/link}ов-Темношкуров.
• Он назначил награды за головы троих: {link:gath-ilzogg}Гат'Илзогг{/link}а, лейтенанта {link:lieutenant-fangore}Фэнгор{/link}а и испепелителя {link:incinerator-gar-im}Гар'им{/link}а.
• Он посылал мольбы о помощи в {link:stormwind-city}Штормград{/link}, в {link:westfall}Западный Край{/link} — Гриану {link:gryan-stoutmantle}Камнегрив{/link}у — и в {link:darkshire}Темнолесье{/link}, лорду Чернодреву.]=],
		},
	},
	chapters = {
		{
			title = "«Озерное государство»",
			hint = "Доставьте донесение магистрата армии в Штормграде.",
			text = [=[Донесение магистрата рассказывало всю мрачную повесть: союз {link:orcs}орк{/link}а и чернокнижника, падение крепости, разрушенный мост, нехватка солдат, еды и бинтов. Генерал в {link:stormwind-city}Штормград{/link}е похвалил его и пообещал подкрепление, как только король даст слово. Соломон прочел ответ дважды. Он счел его загадкой и убоялся, что тот знаменует начало войны, а не ее конец.]=],
		},
		{
			title = "Письма в соседние земли",
			hint = "Доставьте мольбы магистрата в Западный Край и в Темнолесье.",
			text = [=[Затем Соломон обратился к соседям. {link:gryan-stoutmantle}Камнегрив{/link} ответил с тяжелым сердцем: его ополчение вело собственную войну. Лорд Чернодрев счел просьбу близкой к безумию, ибо {link:darkshire}Темнолесье{/link} собрало свой {link:the-night-watch}Ночной Дозор{/link} лишь потому, что {link:stormwind-city}Штормград{/link} покинул и его. Когда оба ответа оказались у него в руках, Соломон понял, что армия ушла из всех трех земель. Он назвал это изменой.]=],
		},
		{
			title = "Истинные хозяева",
			hint = [=[Доставьте тяжкие вести из Пылающих степей в Приозерье и дальше, регенту.]=],
			text = [=[С севера пришла весть, что {link:blackrock-clan}клан Черной горы{/link} — лишь пешки и что за ним стоят черные драконы. Соломон тотчас отправил ее верховному лорду {link:bolvar-fordragon}Болвару Фордрагону{/link}. Регент не прислал в ответ армии. Вместо этого он назначил гонца уполномоченным {link:stormwind-city}Штормград{/link}а, и Соломон заплакал, прочитав этот указ.]=],
		},
	},
	mentions = {
		{ text = "«Гонец в {link:stormwind-city}Штормград{/link}»" },
		{ text = "«Гонец в {link:westfall}Западный Край{/link}»" },
		{ text = "«Гонец в {link:darkshire}Темнолесье{/link}»" },
		{ text = "«РАЗЫСКИВАЕТСЯ: {link:gath-ilzogg}Гат'Илзогг{/link}»" },
		{
			text = [=[«РАЗЫСКИВАЕТСЯ: лейтенант {link:lieutenant-fangore}Фэнгор{/link}»]=],
		},
		{
			text = [=[«РАЗЫСКИВАЕТСЯ: испепелитель {link:incinerator-gar-im}Гар'им{/link}»]=],
		},
		{
			text = [=[«Истинные хозяева», в {link:burning-steppes}Пылающие степи{/link}]=],
		},
	},
	bonds = {
		{ id = "bailiff-conacher", name = "пристав Конахер", note = "служитель его суда" },
		{ id = "marshal-marris", name = "маршал Маррис", note = "командует обороной его города" },
		{ id = "gryan-stoutmantle", name = "Гриан Камнегрив", note = "отказал ему в просьбе" },
		{ id = "lord-ello-ebonlocke", name = "лорд Элло Чернодрев", note = "отказал ему в просьбе" },
		{ id = "bolvar-fordragon", name = "Болвар Фордрагон", note = "регент, к которому он взывает" },
		{ id = "gath-ilzogg", name = "Гат'Илзогг", note = "военачальник, чьей смерти он хочет" },
	},
})

Translate("ruRU", "bailiff-conacher", {
