	},
})

Translate("ruRU", "marshal-marris", {
	title = "Маршал Маррис",
	subtitle = "Маршал Приозерья",
	found = "Северный край Приозерья, у строящегося моста",
	hint = "Поговорите с маршалом, который командует обороной Приозерья.",
	allegiance = "Королевство Штормград · Армия Штормграда",
	aliases = { "Маррис" },
	sections = {
		{
			title = "Обзор",
			text = [=[Маршал Маррис командует солдатами Приозерья. Он проиграл битву за {link:stonewatch-keep}Крепость Каменной Стражи{/link} и теперь должен удержать город тем немногим, что осталось. Это солдат дела. Он знает, что одной храбростью эту войну не выиграть, и считает своих врагов по топорам, сферам и головам, которые ему приносят.]=],
		},
		{
			title = "Значение",
			text = [=[Маррис — меч Приозерья, как {link:magistrate-solomon}Соломон{/link} — его голос. Пока магистрат пишет письма, маршал ведет войну, которую больше никто вести не хочет, против врага, превосходящего его числом в каждой долине.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он держит {link:lakeshire}Приозерье{/link} против клана Черной горы с небольшим гарнизоном.
• Он охотится на скороходов клана Черной горы, которые устраивают засады на дороге к Каменной Страже.
• Он уничтожает темные сферы заклинателей тьмы клана Черной горы.
• Он ведет против орочьих лагерей войну голодом.]=],
		},
	},
	chapters = {
		{
			title = "Угроза Черной горы",
			hint = "Помогите маршалу проредить ряды клана Черной горы.",
			text = [=[{link:orcs}Орки{/link} пришли из Пылающих степей, взяли крепость и заперли жителей Приозерья в их собственном городе. Маррис просил в доказательство их топоры, а затем — голову хитрого орка {link:tharil-zun}Тарил'зун{/link}а, который возглавлял засады на дороге к Каменной Страже.]=],
		},
		{
			title = "Темная магия",
			hint = [=[Принесите маршалу темные сферы заклинателей клана Черной горы.]=],
			text = [=[{link:blackrock-clan}Клан Черной горы{/link} привел с собой заклинателей тьмы, а с ними пришли полночные сферы, оскверненные демонами. Эти сферы сразили многих защитников Красногорья. Маррис не стал их хранить. Все до единой он отослал на уничтожение.]=],
		},
		{
			title = "Пропал без вести",
			hint = "Верните домой солдата, пропавшего у Каменной Стражи.",
			text = [=[{link:corporal-keeshan}Капрал Кишан{/link} вернулся от Скалы Ренда раненый и один. Большая часть его полка полегла вокруг него. Маррис все равно счел это победой и наградил тех, кто привел солдата домой.]=],
		},
	},
	mentions = {
		{ text = "«Блокада клана Черной горы»" },
	},
	bonds = {
		{ id = "magistrate-solomon", name = "магистрат Соломон", note = "управляет городом, который он охраняет" },
		{ id = "corporal-keeshan", name = "капрал Кишан", note = "его пропавший солдат" },
		{ id = "tharil-zun", name = "Тарил'зун", note = "орк, чьей смерти он хотел" },
		{ id = "bellygrub", name = "Обжора", note = "получил от него имя" },
	},
})

Translate("ruRU", "foreman-oslow", {
