Translate("ruRU", "darcy", {
	title = "Дарси",
	subtitle = "Подавальщица таверны Приозерья",
	found = "Таверна Приозерья",
	hint = "Поговорите с подавальщицей в таверне Приозерья.",
	allegiance = "Городок Приозерье",
	sections = {
