Translate("ruRU", "morganth", {
	title = "Моргант",
	subtitle = "Чернокнижник Башни Илгалара",
	found = "Вершина Башни Илгалара",
	hint = "Поднимитесь на Башню Илгалара и сразитесь с ее хозяином.",
	allegiance = "Сам себе господин · гноллы-Темношкуры",
	sections = {
		{
			title = "Обзор",
			text = [=[Моргант — чернокнижник из рода людей, обитающий в Башне {link:tower-of-ilgalar}Илгалар{/link}а. Давным-давно он учился в башне магов {link:stormwind-city}Штормград{/link}а — один из троих, что постигали там науку вместе. Он поддался темным искусствам, и когда не пожелал повернуть назад, его изгнали. С собой он унес запечатанную книгу темной магии. Теперь он повелевает {link:gnolls}гнолл{/link}ами-Темношкурами, говорит с ними через зачарованные подвески и призывает к себе демонов.]=],
		},
		{
			title = "Значение",
			text = [=[Моргант — скрытый виновник разорения Красногорья. Именно его магия питала свирепость клана Черной горы у Крепости Каменной Стражи. Он также соперник верховного мага {link:theocritus}Теокрита{/link}, который давно следит за ним из {link:elwynn-forest}Элвинн{/link}ского леса.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он заключил союз с военачальником {link:gath-ilzogg}Гат'Илзогг{/link}ом и кланом Черной горы и помог им взять {link:stonewatch-keep}Крепость Каменной Стражи{/link}.
• Вскоре после этого он обратился против {link:orcs}орк{/link}ов, возвел собственную башню и привязал {link:gnolls}гнолл{/link}ов-Темношкуров к своей службе.
• Он хранит «Трактат Ура по темной магии», хотя так и не сломал печати, наложенные на него магами {link:stormwind-city}Штормград{/link}а.
• Он ищет {red:scythe-of-elune}Косу Элуны{/red}.]=],
		},
	},
	chapters = {
		{
			title = "Расторгнутый союз",
			hint = "Помогите верховному магу заглянуть в крепость орков.",
			text = [=[Око Азоры показало верховному магу чернокнижника, воюющего с {link:orcs}орк{/link}ами, которым он прежде помогал. Отчего эти двое рассорились, не мог сказать даже магистрат {link:magistrate-solomon}Соломон{/link}. Чтобы узнать больше, {link:theocritus}Теокрит{/link} спрятал глиф на вершине сторожевой башни рядом с Крепостью Каменной Стражи и начал читать мысли орков внутри.]=],
		},
		{
			title = "Коса",
			hint = "Сделайте то, к чему верховный маг не готов сам.",
			text = [=[{link:nak}Нак{/link}онец {link:theocritus}Теокрит{/link} узнал, чего ищет Моргант: {red:scythe-of-elune}Косу Элуны{/red}. Он боялся, что чернокнижник уже нашел эту косу и что {link:stormwind-city}Штормград{/link} скоро ощутит его мощь. Сам верховный маг не желал выходить против него, и потому на Башню {link:tower-of-ilgalar}Илгалар{/link}а вместо него поднялся другой. Подвеска Тени, которую носил Моргант, вернулась в {link:elwynn-forest}Элвиннский лес{/link}, и Теокрит объявил, что королевство спасено от тяжкой беды.]=],
		},
	},
	mentions = {
		{ text = "«Закон магистрата»" },
		{ text = "«Возвращение имущества верховного мага»" },
		{ text = "«Бдительное око»" },
		{ text = "«Трактат Ура по темной магии»" },
	},
	bonds = {
		{ id = "theocritus", name = "Теокрит", note = "его соперник" },
		{ id = "gath-ilzogg", name = "Гат'Илзогг", note = "его бывший союзник" },
		{ id = "lieutenant-fangore", name = "лейтенант Фэнгор", note = "его лейтенант из гноллов" },
		{ id = "shadowhide-gnolls", name = "Гноллы-Темношкуры", note = "его слуги" },
	},
})

