Translate("ruRU", "blackrock-clan", {
	title = "Клан Черной горы",
	aliases = { "клан Черной горы", "орки клана Черной горы" },
	sections = {
		{
			title = "Обзор",
			text = [=[Клан Черной горы — один из старейших и самых воинственных кланов {link:orcs}орков{/link}. Он был хребтом старой {link:horde}Орды{/link} и дал ей двух вождей. Спустя долгое время после поражения Орды клан Черной горы хранит старые обычаи войны, и он никогда не заключал мира с людьми.]=],
		},
		{
			title = "История",
			text = [=[В {link:first-war}Первую войну{/link} вождь клана Чернорук возглавлял Орду как ее вождь, хотя за его спиной за нити дергали другие. Его убил один из своих — {link:orgrim-doomhammer}Оргрим Молот Рока{/link}, воин клана Черной горы, который затем привел Орду к завоеванию {link:stormwind-city}Штормград{/link}а. Во {link:second-war}Вторую войну{/link} эта {link:horde}Орда{/link} была разбита у {link:blackrock-mountain}Черной горы{/link} после того, как {link:anduin-lothar}Андуин Лотар{/link} пал от руки ее вождя. Большинство {link:orcs}орк{/link}ов согнали в лагеря. Те из клана, кто спасся, укрылись в горе, имя которой он носит, и с тех пор удерживают ее вершины.]=],
		},
		{
			title = "В Красногорье",
			text = [=[Теперь клан Черной горы пришел на юг из {link:burning-steppes}Пылающих степей{/link}. Под началом военачальника {link:gath-ilzogg}Гат'Илзогг{/link}а и с темной магией чернокнижника {link:morganth}Моргант{/link}а {link:orcs}орк{/link}и взяли {link:stonewatch-keep}Крепость Каменной Стражи{/link} и обрушили мост через {link:lake-everstill}Озеро Безмолвия{/link}. Их скороходы устраивают засады на дорогах, их заклинатели тьмы носят сферы, оскверненные демонами, а их воители стоят лагерем у северного перевала. Еще один боевой отряд вошел на дальний юго-восток через Долину Ренда. Но они зашли так далеко вглубь королевства, что вынуждены добывать еду и оружие в холмах, и {link:lakeshire}Приозерье{/link} надеется взять их измором.]=],
		},
		{
			title = "Новая Орда",
			text = [=[Не всякий воин клана остался с ним. {link:eitrigg}Эйтригг{/link}, некогда служивший вождю клана Черной горы, возненавидел поклонников демонов, сбивших его народ с пути. Теперь он служит вождю {link:thrall}Траллу{/link} в {link:orgrimmar}Оргриммаре{/link}, вдали от горы своего старого клана.]=],
		},
	},
})

Translate("ruRU", "shadowhide-gnolls", {
	title = "Гноллы-Темношкуры",
	aliases = { "гноллы-Темношкуры", "Темношкуры" },
	sections = {
		{
			title = "Обзор",
			text = [=[Темношкуры — клан {link:gnolls}гноллов{/link}, обитающий в Долине {link:galardell-valley}Галарделл{/link} на северо-востоке Красногорья. Они служат чернокнижнику {link:morganth}Моргант{/link}у. Их вожак — лейтенант {link:lieutenant-fangore}Фэнгор{/link}. Их ткачи тьмы творят темную магию, их убийцы бьют незримо, а их душегубы нападают равно на {link:orcs}орк{/link}ов и на людей.]=],
		},
		{
			title = "Связанные подвесками",
			text = [=[Каждый Темношкур носит подвеску, через которую {link:morganth}Моргант{/link} говорит с ними. Верховный маг {link:theocritus}Теокрит{/link} потратил месяцы, пытаясь проникнуть в эти подвески. Ему удалось послать сообщение через некоторые из них, и он надеется однажды послать через них удар, который заморозит каждого {link:gnolls}гнолл{/link}а, носящего такую подвеску.]=],
		},
		{
			title = "Перед законом",
			text = [=[Суд Приозерья объявил Темношкуров виновными в пособничестве преступнику перед королевством — в преступлении, которое карается смертью. {link:bailiff-conacher}Пристав Конахер{/link} платит за их подвески как за доказательство, а магистрат назначил награду за самого их вожака.]=],
		},
		{
			title = "Враги всем",
			text = [=[Темношкуры не друзья клану Черной горы. Когда {link:morganth}Моргант{/link} обратился против своих союзников-{link:orcs}орк{/link}ов, его {link:gnolls}гнолл{/link}ы обратились вместе с ним, и орки гибли от их рук так же верно, как и люди.]=],
		},
	},
})

Translate("ruRU", "redridge-gnolls", {
	title = "Гноллы Красногорья",
	aliases = { "гноллы Красногорья", "стая Красногорья" },
	sections = {
		{
			title = "Обзор",
			text = [=[Гноллы Красногорья — старая стая {link:gnolls}гнолл{/link}ов Красногорья, отличная от Темношкуров, которые служат чернокнижнику. Они не служат ни чернокнижнику, ни {link:orcs}орк{/link}ам. Их громилы и мистики бродят по холмам к северу от Приозерья, а их браконьеры и дворняги стоят лагерем вдоль южной дороги. Их вожак — {link:yowler}Ревун{/link}, чье логово находится в Каньонах Красногорья и чей вой доносится до самого Приозерья.]=],
		},
		{
			title = "Их обычаи",
			text = [=[Гноллы Красногорья берут то, что война оставляет без охраны. Они захватили караван, который вез железо для моста через {link:lake-everstill}Озеро Безмолвия{/link}. Они крадут лошадей из конюшни Приозерья. Они заняли {link:rethban-caverns}Пещеры Ретбана{/link}, где их чернорабочие добывают руду, которую прежде добывал город. Порядка у них мало, но силу они уважают превыше всего. {link:deputy-feldon}Уполномоченный Фелдон{/link} надеется, что гибель самых свирепых их молотильщиков научит остальных держаться холмов. В Пещерах Ретбана стаей, что их удерживает, предводительствует {link:gnolls}гнолл{/link} по имени Ардо Грязная Лапа.]=],
		},
	},
})
